// subscriptionUniqueKeys are the conflict targets of Subscription's unique keys, and
// the assignment of the update an upsert that sets nothing names, which its
// WHERE FALSE never runs (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert reads back when it leaves them as they
// were, empty for a key over an expression, and that key's read of the row
// that holds one input's value of it, empty for a key over columns; and the
// key's columns as a batch insert's cells name them (D89).
var subscriptionUniqueKeys = map[SubscriptionUniqueKey]struct {
	conflict, keep, rows, held string
	columns                    []string
}{
	SubscriptionUniqueById:              {`(id)`, `id = subscription.id`, `SELECT "id", "subscriber", "label_id", "deleted_at", "deleted_by" FROM subscription WHERE (id) IN (%s)`, ``, []string{`id`}},
	SubscriptionUniqueBySubscriberLabel: {`(subscriber, label_id) WHERE deleted_at IS NULL`, `subscriber = subscription.subscriber`, `SELECT "id", "subscriber", "label_id", "deleted_at", "deleted_by" FROM subscription WHERE (subscriber, label_id) IN (%s) AND (deleted_at IS NULL)`, ``, []string{`subscriber`, `label_id`}},
}

// subscriptionKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func subscriptionKeyOf(on SubscriptionUniqueKey, row *types.Subscription) (string, bool) {
	switch on {
	case SubscriptionUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	case SubscriptionUniqueBySubscriberLabel:
		return upsertKeyText(upsertKeyValue(row.Subscriber, false), upsertKeyValue(row.Label.Id, false))
	}
	return "", false
}

