// UpsertOne inserts input, or, when a row already holds its value of the
// unique key on, applies update to that row instead, and returns the row
// (D79). The insert writes what CreateOne writes and the update what
// UpdateOne writes, updated_at and updated_by among it, but an update that
// sets no field leaves the row as it is. A soft-deleted row that holds the key is
// left as it is, and UpsertOne returns ErrNotFound.
func (r *SubscriptionRepository) UpsertOne(ctx context.Context, input *types.Subscription, on SubscriptionUniqueKey, update *SubscriptionUpdate) (*types.Subscription, error) {
	result, err := r.UpsertOneResult(ctx, input, on, update, nil)
	if err != nil {
		return nil, err
	}
	return result.Row, nil
}

// UpsertOneResult is UpsertOne, and what it did with the row: inserted it,
// updated the row that held the key, or left that row as it was (D89).
// With opts.OnlyIfChanged it updates the row only when a field the update
// sets differs from what the row holds, which it reads back otherwise. One
// whose update sets no field updates nothing, so the row keeps its version
// and no trigger fires, and reads the row back. A write that
// may take more than one statement runs in a transaction of its own when
// none is open.
func (r *SubscriptionRepository) UpsertOneResult(ctx context.Context, input *types.Subscription, on SubscriptionUniqueKey, update *SubscriptionUpdate, opts *UpsertOptions) (UpsertResult[*types.Subscription], error) {
	var none UpsertResult[*types.Subscription]
	key, ok := subscriptionUniqueKeys[on]
	if !ok {
		return none, fmt.Errorf("orm: Subscription has no unique key %q", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if opts.OnlyIfChanged && key.rows == "" {
		return none, upsertExpressionKey("UpsertOneResult", "Subscription", string(on))
	}
	if update == nil {
		update = &SubscriptionUpdate{}
	}
	write := func(repo *SubscriptionRepository) (UpsertResult[*types.Subscription], error) {
		result, err := repo.upsertRow(ctx, input, on, update, opts.OnlyIfChanged)
		if err != nil {
			return none, err
		}
		return *result, nil
	}
	if !opts.OnlyIfChanged && subscriptionUpdateSetsField(update) {
		return write(r)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (UpsertResult[*types.Subscription], error) {
		return write(&SubscriptionRepository{tx: tx, txDB: r.database()})
	})
}

// subscriptionUpdateSetsField reports whether update sets a field, a value or a
// null: UpdatedBy alone sets none, but stamps the row an update that sets
// one changes.
func subscriptionUpdateSetsField(update *SubscriptionUpdate) bool {
	return update != nil && *update != (SubscriptionUpdate{UpdatedBy: update.UpdatedBy})
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
